{"file_text": "<div class="card mb-3">
    <div class="card-body">
        <div class="d-flex justify-content-between align-items-center mb-3">
            <h6 class="card-title mb-0">Position @(Index + 1)</h6>
            @if (ShowRemove)
            {
                <button type="button" class="btn btn-outline-danger btn-sm" @onclick="OnRemove">Remove</button>
            }
        </div>

        <div class="row g-3">
            <div class="col-md-6">
                <label class="form-label">Company Name <span class="text-danger">*</span></label>
                <input type="text" class="form-control" value="@Company" @onchange="e => UpdateField(nameof(Company), e)" />
            </div>
            <div class="col-md-6">
                <label class="form-label">Job Title <span class="text-danger">*</span></label>
                <input type="text" class="form-control" value="@Title" @onchange="e => UpdateField(nameof(Title), e)" />
            </div>
            <div class="col-md-4">
                <label class="form-label">Start Date <span class="text-danger">*</span></label>
                <input type="date" class="form-control" value="@StartDate?.ToString("yyyy-MM-dd")" @onchange="e => UpdateField(nameof(StartDate), e)" />
            </div>
            <div class="col-md-4">
                <label class="form-label">End Date</label>
                <input type="date" class="form-control" value="@EndDate?.ToString("yyyy-MM-dd")" disabled="@IsCurrent" @onchange="e => UpdateField(nameof(EndDate), e)" />
            </div>
            <div class="col-md-4 d-flex align-items-end">
                <div class="form-check mb-2">
                    <input class="form-check-input" type="checkbox" id="current-@Index" checked="@IsCurrent" @onchange="OnCurrentChanged" />
                    <label class="form-check-label" for="current-@Index">Currently working here</label>
                </div>
            </div>
            <div class="col-12">
                <label class="form-label">Description</label>
                <textarea class="form-control" rows="3" @onchange="e => UpdateField(nameof(Description), e)">@Description</textarea>
            </div>
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public int Index { get; set; }
    [Parameter] public string Company { get; set; } = "";
    [Parameter] public string Title { get; set; } = "";
    [Parameter] public DateTime? StartDate { get; set; }
    [Parameter] public DateTime? EndDate { get; set; }
    [Parameter] public bool IsCurrent { get; set; }
    [Parameter] public string Description { get; set; } = "";
    [Parameter] public bool ShowRemove { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }
    [Parameter] public EventCallback<WorkEntryUpdate> OnChanged { get; set; }

    public record WorkEntryUpdate(int Index, string Field, object? Value);

    private async Task UpdateField(string field, ChangeEventArgs e)
    {
        object? value = field switch
        {
            nameof(StartDate) or nameof(EndDate) => string.IsNullOrEmpty(e.Value?.ToString()) ? null : DateTime.Parse(e.Value!.ToString()!),
            _ => e.Value?.ToString() ?? ""
        };
        await OnChanged.InvokeAsync(new WorkEntryUpdate(Index, field, value));
    }

    private async Task OnCurrentChanged(ChangeEventArgs e)
    {
        var isCurrent = (bool)(e.Value ?? false);
        await OnChanged.InvokeAsync(new WorkEntryUpdate(Index, nameof(IsCurrent), isCurrent));
        if (isCurrent)
        {
            await OnChanged.InvokeAsync(new WorkEntryUpdate(Index, nameof(EndDate), null));
        }
    }
}
