+<h4 class="mb-3">Work History</h4>
+
+@if (!string.IsNullOrEmpty(errorMessage))
+{
+    <div class="alert alert-danger">@errorMessage</div>
+}
+
+@for (int i = 0; i < Entries.Count; i++)
+{
+    var entry = Entries[i];
+    <WorkEntryForm Index="i"
+                   Company="@entry.Company"
+                   Title="@entry.Title"
+                   StartDate="@entry.StartDate"
+                   EndDate="@entry.EndDate"
+                   IsCurrent="@entry.IsCurrent"
+                   Description="@entry.Description"
+                   ShowRemove="@(Entries.Count > 1)"
+                   OnRemove="() => RemoveEntry(entry)"
+                   OnChanged="HandleEntryChanged" />
+}
+
+<button type="button" class="btn btn-outline-secondary mb-3" @onclick="AddEntry">
+    + Add Another Position
+</button>
+
+<div class="d-flex justify-content-between mt-4">
+    <button type="button" class="btn btn-outline-secondary" @onclick="OnBack">Back</button>
+    <button type="button" class="btn btn-primary" @onclick="HandleNext">Next</button>
+</div>
+
+@code {
+    [Parameter] public List<WorkEntryModel> Entries { get; set; } = new();
+    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }
+    [Parameter, EditorRequired] public EventCallback<List<WorkEntryModel>> OnNext { get; set; }
+
+    private string? errorMessage;
+
+    public class WorkEntryModel
+    {
+        public string Company { get; set; } = "";
+        public string Title { get; set; } = "";
+        public DateTime? StartDate { get; set; }
+        public DateTime? EndDate { get; set; }
+        public bool IsCurrent { get; set; }
+        public string Description { get; set; } = "";
+    }
+
+    private void AddEntry()
+    {
+        Entries.Add(new WorkEntryModel());
+    }
+
+    private void RemoveEntry(WorkEntryModel entry)
+    {
+        if (Entries.Count > 1)
+        {
+            Entries.Remove(entry);
+        }
+    }
+
+    private void HandleEntryChanged(WorkEntryForm.WorkEntryUpdate update)
+    {
+        var entry = Entries[update.Index];
+        switch (update.Field)
+        {
+            case nameof(WorkEntryModel.Company): entry.Company = (string)update.Value!; break;
+            case nameof(WorkEntryModel.Title): entry.Title = (string)update.Value!; break;
+            case nameof(WorkEntryModel.StartDate): entry.StartDate = (DateTime?)update.Value; break;
+            case nameof(WorkEntryModel.EndDate): entry.EndDate = (DateTime?)update.Value; break;
+            case nameof(WorkEntryModel.IsCurrent): entry.IsCurrent = (bool)update.Value!; break;
+            case nameof(WorkEntryModel.Description): entry.Description = (string)update.Value!; break;
+        }
+    }
+
+    private async Task HandleNext()
+    {
+        errorMessage = null;
+
+        foreach (var entry in Entries)
+        {
+            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title) || entry.StartDate is null)
+            {
+                errorMessage = "Each position requires a company name, job title, and start date.";
+                return;
+            }
+        }
+
+        await OnNext.InvokeAsync(Entries);
+    }
+}
+

