+            case nameof(ReferenceModel.Relationship): refModel.Relationship = update.Value; break;
+            case nameof(ReferenceModel.Email): refModel.Email = update.Value; break;
+            case nameof(ReferenceModel.Phone): refModel.Phone = update.Value; break;
+        }
+    }
+
+    private async Task HandleNext()
+    {
+        errorMessage = null;
+
+        foreach (var r in References)
+        {
+            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship) ||
+                string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
+            {
+                errorMessage = "All fields are required for each reference.";
+                return;
+            }
+        }
+
+        await OnNext.InvokeAsync(References);
+    }
+}
