arguments.file_text:
@page "/apply"
@using sv_01ba40df1e524e23bb6280b26841dd6c.Models
@using sv_01ba40df1e524e23bb6280b26841dd6c.Services
@using sv_01ba40df1e524e23bb6280b26841dd6c.Components.Pages.Apply

@inject IApplicationService ApplicationService

@rendermode InteractiveServer

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h2 class="mb-4">Job Application</h2>

    <StepIndicator CurrentStep="currentStep" CompletedSteps="completedSteps" OnStepClicked="GoToStep" />

    <div class="mt-4">
        @switch (currentStep)
        {
            case 0:
                <PersonalInfoStep FullName="@personalFullName"
                                  Email="@personalEmail"
                                  Phone="@personalPhone"
                                  Address="@personalAddress"
                                  OnNext="HandlePersonalNext" />
                break;

            case 1:
                <WorkHistoryStep Entries="workEntries" OnBack="GoBack" OnNext="HandleWorkNext" />
                break;

            case 2:
                <ReferencesStep References="references" OnBack="GoBack" OnNext="HandleReferencesNext" />
                break;

            case 3:
                <CoverLetterStep CoverLetter="@coverLetter" OnBack="GoBack" OnNext="HandleCoverLetterNext" />
                break;

            case 4:
                <ReviewStep Personal="@GetPersonalInfo()"
                            WorkEntries="@GetWorkEntries()"
                            References="@GetReferences()"
                            CoverLetter="@coverLetter"
                            Submitted="@submitted"
                            ApplicationId="@applicationId"
                            ErrorMessage="@submitError"
                            OnBack="GoBack"
                            OnEditSection="GoToStep"
                            OnSubmit="HandleSubmit" />
                break;
        }
    </div>
</div>

@code {
    private int currentStep;
    private readonly HashSet<int> completedSteps = new();

    // Step 1 state
    private string personalFullName = "";
    private string personalEmail = "";
    private string personalPhone = "";
    private string personalAddress = "";

    // Step 2 state
    private List<WorkHistoryStep.WorkEntryModel> workEntries = new() { new() };

    // Step 3 state
    private List<ReferencesStep.ReferenceModel> references = new() { new(), new() };

    // Step 4 state
    private string coverLetter = "";

    // Step 5 state
    private bool submitted;
    private int applicationId;
    private string? submitError;

    private void GoToStep(int step)
    {
        if (completedSteps.Contains(step) || step == currentStep)
        {
            currentStep = step;
        }
    }

    private void GoBack()
    {
        if (currentStep > 0)
        {
            currentStep--;
        }
    }

    private void HandlePersonalNext(PersonalInfo info)
    {
        personalFullName = info.FullName;
        personalEmail = info.Email;
        personalPhone = info.Phone;
        personalAddress = info.Address;
        completedSteps.Add(0);
        currentStep = 1;
    }

    private void HandleWorkNext(List<WorkHistoryStep.WorkEntryModel> entries)
    {
        workEntries = entries;
        completedSteps.Add(1);
        currentStep = 2;
    }

    private void HandleReferencesNext(List<ReferencesStep.ReferenceModel> refs)
    {
        references = refs;
        completedSteps.Add(2);
        currentStep = 3;
    }

    private void HandleCoverLetterNext(string text)
    {
        coverLetter = text;
        completedSteps.Add(3);
        currentStep = 4;
    }

    private async Task HandleSubmit()
    {
        submitError = null;
        try
        {
            var application = new JobApplication(
                GetPersonalInfo(),
                new WorkHistory(GetWorkEntries()),
                GetReferences(),
                coverLetter
            );

            applicationId = await ApplicationService.SubmitApplicationAsync(application);
            submitted = true;
        }
        catch (Exception ex)
        {
            submitError = $"Submission failed: {ex.Message}";
        }
    }

    private PersonalInfo GetPersonalInfo() =>
        new(personalFullName, personalEmail, personalPhone, personalAddress);

    private List<WorkEntry> GetWorkEntries() =>
        workEntries.Select(e => new WorkEntry(
            e.Company, e.Title, e.StartDate ?? DateTime.MinValue, e.IsCurrent ? null : e.EndDate, e.Description
        )).ToList();

    private List<Reference> GetReferences() =>
        references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();
}

@page "/apply"
