1. <div class="card mb-3">
2.     <div class="card-body">
3.         <div class="d-flex justify-content-between align-items-center mb-3">
4.             <h6 class="card-title mb-0">Reference @(Index + 1)</h6>
5.             @if (ShowRemove)
6.             {
7.                 <button type="button" class="btn btn-outline-danger btn-sm" @onclick="OnRemove">Remove</button>
8.             }
9.         </div>
10. 
11.         <div class="row g-3">
12.             <div class="col-md-6">
13.                 <label class="form-label">Full Name <span class="text-danger">*</span></label>
14.                 <input type="text" class="form-control" value="@Name" @onchange="e => Update(nameof(Name), e.Value?.ToString() ?? "")" />
15.             </div>
16.             <div class="col-md-6">
17.                 <label class="form-label">Relationship <span class="text-danger">*</span></label>
18.                 <input type="text" class="form-control" value="@Relationship" @onchange="e => Update(nameof(Relationship), e.Value?.ToString() ?? "")" />
19.             </div>
20.             <div class="col-md-6">
21.                 <label class="form-label">Email <span class="text-danger">*</span></label>
22.                 <input type="email" class="form-control" value="@Email" @onchange="e => Update(nameof(Email), e.Value?.ToString() ?? "")" />
23.             </div>
24.             <div class="col-md-6">
25.                 <label class="form-label">Phone <span class="text-danger">*</span></label>
26.                 <input type="tel" class="form-control" value="@Phone" @onchange="e => Update(nameof(Phone), e.Value?.ToString() ?? "")" />
27.             </div>
28.         </div>
29.     </div>
30. </div>
31. 
32. @code {
33.     [Parameter, EditorRequired] public int Index { get; set; }
34.     [Parameter] public string Name { get; set; } = "";
35.     [Parameter] public string Relationship { get; set; } = "";
36.     [Parameter] public string Email { get; set; } = "";
37.     [Parameter] public string Phone { get; set; } = "";
38.     [Parameter] public bool ShowRemove { get; set; }
39.     [Parameter] public EventCallback OnRemove { get; set; }
40.     [Parameter] public EventCallback<ReferenceUpdate> OnChanged { get; set; }
41. 
42.     public record ReferenceUpdate(int Index, string Field, string Value);
43. 
44.     private async Task Update(string field, string value)
45.     {
46.         await OnChanged.InvokeAsync(new ReferenceUpdate(Index, field, value));
47.     }
48. }
